create index if not exists credential_broker_agent on credential_broker (agent_id, status);

-- comms: the signed room log. `comms_events` is the authority; the channel
-- conversation is a view of it, which is why a message carries the event id.
create table if not exists comms_identities (
    agent_id text primary key references agents(id) on delete cascade,
    team_id text not null references teams(id) on delete cascade,
    handle text not null default '',
    pubkey text not null unique,
    seckey text not null default '',
    custody text not null default 'local',
    relays text not null default '[]',
    created_date double precision not null
);

create table if not exists comms_members (
    room_id text not null references channels(id) on delete cascade,
    member_id text not null,
    member_kind text not null default 'agent',
    pubkey text not null default '',
    role text not null default 'member',
    joined_date double precision not null,
    primary key (room_id, member_id)
);

create table if not exists comms_events (
    seq bigint generated by default as identity primary key,
    id text not null unique,
    room_id text not null,
    kind integer not null,
    pubkey text not null,
    author_id text not null default '',
    author_kind text not null default 'external',
    content text not null default '',
    tags text not null default '[]',
    created_at integer not null,
    sig text not null default '',
    received_at double precision not null
);
create index if not exists comms_events_room on comms_events (room_id, seq);
create index if not exists comms_events_created on comms_events (room_id, created_at);

create table if not exists comms_cursors (
    name text primary key,
    room_id text not null default '',
    seq integer not null default 0,
    updated_date double precision not null
);

create table if not exists comms_bridges (
    room_id text not null references channels(id) on delete cascade,
    transport text not null,
    config text not null default '{}',
    cursor_seq integer not null default 0,
    last_sync double precision,
    last_error text not null default '',
    primary key (room_id, transport)
);
-- a saga: steps in order, each with an undo, reversed when a later step fails.
create table if not exists sagas (
    id text primary key,
    team_id text not null,
    name text not null default '',
    status text not null default 'draft',
    steps text not null default '[]',
    context text not null default '{}',
    error text not null default '',
    created_date double precision not null,
    updated_date double precision not null,
    finished_date double precision
);
create index if not exists sagas_team on sagas (team_id, status);

create table if not exists saga_steps (
    id text primary key,
    saga_id text not null references sagas(id) on delete cascade,
    position integer not null,
    name text not null,
    status text not null default 'pending',
    result text not null default '{}',
    undo_result text not null default '{}',
    error text not null default '',
    started_date double precision,
    finished_date double precision,
    unique (saga_id, position)
);
create index if not exists saga_steps_saga on saga_steps (saga_id, position);

-- a poll: check an external fact on a schedule until a rule says stop.
create table if not exists polls (
    id text primary key,
    team_id text not null,
    name text not null default '',
    check_op text not null,
    check_args text not null default '{}',
    until text not null default '{}',
    interval double precision not null default 60,
    max_interval double precision not null default 3600,
    backoff double precision not null default 1.0,
    max_attempts integer not null default 20,
    deadline double precision,
    on_satisfy text not null default '',
    on_expire text not null default '',
    status text not null default 'waiting',
    attempts integer not null default 0,
    next_at double precision,
    last_result text not null default '{}',
    created_date double precision not null,
    updated_date double precision not null,
    finished_date double precision
);
create index if not exists polls_team on polls (team_id, status);

-- one row per browser an agent has been given: which provider, whose task, and
-- whether the profile survives. a browser nobody can find is a login nobody can revoke.
create table if not exists browser_sessions (
    id text primary key,
    team_id text not null default '',
    agent_id text not null,
    task_id text not null default '',
    provider text not null,
    scope text not null default 'task',
    state text not null default 'ready',
    cdp_url text not null default '',
    live_url text not null default '',
    profile_dir text not null default '',
    handle text not null default '{}',
    created_date double precision not null,
    closed_date double precision
);
create index if not exists browser_sessions_agent on browser_sessions (agent_id, state);

create table if not exists poll_attempts (
    id text primary key,
    poll_id text not null references polls(id) on delete cascade,
    attempt integer not null,
    status text not null,
    result text not null default '{}',
    error text not null default '',
    created_date double precision not null,
    unique (poll_id, attempt)
);

-- a guardrail answers without a person. a gate asks a human; a guardrail is the
-- standing limit that still holds at 3am when nobody will answer. `value` is json so
-- a list kind and a number kind are the same column.
create table if not exists guardrails (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null default '',
    kind text not null,
    value text not null default 'null',
    status text not null default 'active',
    actor text not null default 'human',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists guardrails_scope on guardrails (team_id, agent_id, status);

-- self improvement: an agent proposes, a person disposes, and the proposal is a row
-- so the profile can say where an instruction came from.
create table if not exists lessons (
    id text primary key,
    team_id text not null,
    agent_id text not null references agents(id) on delete cascade,
    run_id text not null default '',
    task_id text not null default '',
    statement text not null,
    status text not null default 'proposed',
    write_as text not null default '',
    actor text not null default 'agent',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists lessons_agent on lessons (agent_id, status);

-- a fan-out closes on a record: an explicit partition map, a join rule, a deadline and
-- the reports. "three of five lanes answered" and "all five answered" must not look alike.
create table if not exists convergences (
    id text primary key,
    team_id text not null,
    task_id text not null references tasks(id) on delete cascade,
    parent text not null default '',
    join_rule text not null default 'all',
    quorum integer,
    deadline double precision,
    partitions text not null default '{}',
    reports text not null default '[]',
    status text not null default 'open',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists convergences_task on convergences (task_id, status);

-- a handoff is the atomic unit of delegation: state crosses the boundary, a summary
-- does not, so an offer carries a reference and a precondition and never a paragraph.
create table if not exists delegations (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    task_id text not null default '',
    from_agent_id text not null,
    to_agent_id text not null,
    payload_ref text not null,
    precondition text not null,
    acceptance_required integer not null default 1,
    timeout_seconds double precision not null default 3600,
    state text not null default 'offered',
    note text not null default '',
    offered_at double precision not null,
    accepted_at double precision,
    reason text not null default '',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists delegations_team on delegations (team_id, state, created_date);
create index if not exists delegations_to on delegations (to_agent_id, state);

-- a project is the unit above a card: a phase, a gate over rows, and kill criteria
-- declared before the sunk cost exists.
create table if not exists projects (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    name text not null,
    phase text not null default 'inception',
    started_at double precision not null,
    phase_started_at double precision not null,
    objective_ref text not null default '',
    slices text not null default '[]',
    unit_cost_ceiling_cents integer not null default 0,
    unit_price_cents integer,
    min_margin_pct double precision,
    kill_criteria text not null default '[]',
    closed_reason text not null default '',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists projects_team on projects (team_id, phase);

-- a claim is the unit of discourse: a fact needs evidence, a plan may not be stated as
-- a fact, and a synthesis has to account for every claim it was given.
create table if not exists claims (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    thread text not null,
    message_id text not null default '',
    kind text not null default 'inference',
    statement text not null,
    evidence text not null default '',
    confidence double precision not null default 0.5,
    basis text not null default '',
    by_agent text not null default '',
    opposes text not null default '[]',
    created_date double precision not null
);
create index if not exists claims_thread on claims (team_id, thread, created_date);

-- a limit nothing counts is a wish: one row per refusal, so "why is this seat frozen"
-- is a query.
create table if not exists strikes (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null references agents(id) on delete cascade,
    code text not null default '',
    tool text not null default '',
    note text not null default '',
    cleared_by text not null default '',
    created_date double precision not null
);
create index if not exists strikes_agent on strikes (agent_id, cleared_by);

-- a wall is only a wall if the crossing is declared: direction, kinds, rate, expiry.
create table if not exists crossings (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    from_scope text not null,
    to_scope text not null,
    kinds text not null default '[]',
    max_per_hour integer not null default 0,
    max_bytes integer,
    expires_at double precision not null,
    authorized_by text not null default '',
    reason text not null default '',
    revoke_mode text not null default 'drain',
    enabled integer not null default 1,
    tokens double precision not null default 0,
    last_refill_at double precision not null,
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists crossings_pair on crossings (team_id, from_scope, to_scope);

-- an objective is a metric with a baseline, a target and a deadline. replenishment reads it
-- against the clock, so being behind is a comparison rather than a mood.
create table if not exists objectives (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    name text not null,
    baseline double precision not null,
    target double precision not null,
    deadline double precision not null,
    observed_since double precision,
    kinds text not null default '[]',
    wip_limit integer not null default 2,
    status text not null default 'active',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists objectives_team on objectives (team_id, status);

-- a measurement is an observation from outside. the first one starts the period, because
-- measuring from the latest makes every objective look ahead of itself.
create table if not exists measurements (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    objective_id text not null references objectives(id) on delete cascade,
    value double precision not null,
    computed_at double precision not null
);
create index if not exists measurements_objective on measurements (objective_id, computed_at);

-- budget as a reservation: the check and the claim are the same act, so two parallel
-- cards cannot both read the same under-budget number and both proceed.
create table if not exists budget_reservations (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    task_id text not null default '',
    run_id text not null default '',
    agent_id text not null default '',
    amount_cents double precision not null,
    currency text not null default 'usd',
    state text not null default 'held',
    reason text not null default '',
    settled_cents double precision,
    over_spend integer not null default 0,
    created_date double precision not null,
    settled_at double precision,
    updated_date double precision not null
);
create index if not exists budget_reservations_team on budget_reservations (team_id, state, created_date);

-- an eval: a grid of scenarios and candidates, one deterministic scorer, one row per
-- cell. the grid is stored with the run so a report can still be read after the code
-- that produced it has moved on.
create table if not exists eval_runs (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    name text not null default '',
    scenarios text not null default '[]',
    candidates text not null default '[]',
    scorer text not null default '{}',
    status text not null default 'draft',
    summary text not null default '{}',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists eval_runs_team on eval_runs (team_id, created_date);

create table if not exists eval_cases (
    id text primary key,
    eval_id text not null references eval_runs(id) on delete cascade,
    scenario_id text not null,
    candidate_id text not null,
    output text not null default '',
    score double precision not null default 0,
    detail text not null default '',
    created_date double precision not null
);
create index if not exists eval_cases_eval on eval_cases (eval_id, candidate_id);

-- the curated knowledge base: what would take time to explain again, and what a
-- capable agent would not already know from context.
create table if not exists knowledge_entries (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null default '',
    kind text not null,
    title text not null,
    body text not null,
    symptom text not null default '',
    workaround text not null default '',
    tags text not null default '[]',
    source text not null default '',
    status text not null default 'active',
    created_date double precision not null,
    updated_date double precision not null
);
create unique index if not exists knowledge_title on knowledge_entries (team_id, kind, title);

-- intent: what a crew is for, written down, versioned, and read back into every run.
-- a task is what to do; an intent is why, and what would make the doing wrong.
create table if not exists intents (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null default '',
    kind text not null default 'direction',
    statement text not null,
    rationale text not null default '',
    status text not null default 'active',
    version integer not null default 1,
    supersedes text not null default '',
    actor text not null default 'human',
    created_date double precision not null,
    updated_date double precision not null
);
create index if not exists intents_team on intents (team_id, status);

-- routines: the recurring work a crew does on a cadence, with a row per day it was
-- due. schedules enqueue a job; a routine is a promise that leaves a trace when kept
-- and a miss when not, which is the difference between recurring and repeated.
create table if not exists routines (
    id text primary key,
    team_id text not null references teams(id) on delete cascade,
    agent_id text not null default '',
    name text not null,
    description text not null default '',
    cadence text not null default 'daily',
    weekday integer not null default 0,
    hour integer not null default 8,
    steps text not null default '[]',
    required_skills text not null default '[]',
    status text not null default 'active',
    created_date double precision not null,
    updated_date double precision not null
);
create unique index if not exists routines_name on routines (team_id, name);

create table if not exists routine_runs (
    id text primary key,
    routine_id text not null references routines(id) on delete cascade,
    team_id text not null,
    on_date text not null,
    status text not null default 'open',
    task_id text not null default '',
    notes text not null default '',
    created_date double precision not null,
    updated_date double precision not null
);
create unique index if not exists routine_runs_day on routine_runs (routine_id, on_date);
